<template>
  <main class="content-page camp-page"><header class="camp-heading"><div><p class="section-kicker">AN ORIGINAL SPACE GAME / EMBER CAMP</p><h1>余烬营地<span>把一片废墟，变成家。</span></h1><p>白天采集与建造，夜晚守住基地。供电、补给和布局，都由你决定。</p></div><div class="camp-heading-actions"><button type="button" class="text-button" @click="sound=!sound">{{sound?'关闭音效':'开启音效'}}</button><button type="button" class="text-button" @click="help=!help">{{help?'收起玩法说明':'玩法说明'}}</button></div></header>
    <section v-if="help" class="camp-help"><h2>从第一座菜地开始。</h2><p>① WASD / 方向键移动，靠近树、废料箱、补给按 E 采集。② 选择建筑，在绿格点击放置；也可调整格位后点“确认建造”。③ 建好菜地和净水站，给炮塔供电。④ 夜里按住空格主动防卫、Shift 冲刺；受损设施附近按 E 维修。⑤ 守过三夜，救援到达。</p><p>基地自带 1 电力与一座炮塔。每个黎明需要 2 食物、2 饮水；菜地和净水站各产 3。炮塔每座需要 1 电力，发电机提供 2。资源不足、断电或设施被毁都会真实影响结果。地图上方为北；移动方向随俯视相机投影。你可以随时暂停，不保存或上传进度。</p></section>
    <div class="camp-resources" aria-label="营地资源"><div v-for="(name,id) in resourceNames" :key="id"><span>{{name}}</span><strong :data-resource="id">{{hud.resources[id]}}</strong></div><div><span>电力使用 / 容量</span><strong>{{hud.power.demand}} / {{hud.power.capacity}}</strong></div><div><span>营地居民</span><strong>{{hud.crew}} 人</strong></div></div>
    <div class="camp-layout"><section><div ref="stage" class="camp-stage" :class="{'is-expanded':expanded}" tabindex="0" aria-label="余烬营地 3D 建造与生存区域" :data-phase="phase" :data-day="hud.day" :data-cycle="hud.cycle.toFixed(2)" :data-x="hud.player.x.toFixed(2)" :data-z="hud.player.z.toFixed(2)" :data-buildings="hud.buildings.length" :data-harvests="hud.harvests" :data-kills="hud.kills" @pointerdown="focus" @pointermove="point" @click="placeScene"><div ref="mount" class="camp-canvas" />
      <div class="camp-hud"><div><span>{{hud.night?'夜袭':'建设时段'}} · 第 {{Math.min(hud.day,3)}} 天</span><strong>{{hud.night?`${hud.enemies.length} 个敌人`:`${Math.max(0,Math.ceil((difficulty==='relaxed'?40:34)-hud.cycle))} 秒后入夜`}}</strong></div><div><span>基地耐久 {{Math.ceil(hud.base.hp)}} / {{hud.base.maxHp}}</span><meter :value="hud.base.hp" min="0" :max="hud.base.maxHp" aria-label="基地耐久" /></div><div><span>角色生命 {{Math.ceil(hud.player.hp)}}</span><meter :value="hud.player.hp" min="0" max="100" aria-label="角色生命" /></div></div>
      <div class="camp-view-buttons"><button type="button" @click.stop="toggleScene">{{expanded?'收起营地':'放大营地'}}</button><button type="button" aria-label="放大场景视角" @click.stop="scene?.zoom(-2);draw()">＋</button><button type="button" aria-label="缩小场景视角" @click.stop="scene?.zoom(2);draw()">−</button><button v-if="phase==='playing'" type="button" @click.stop="pause">暂停</button></div>
      <div v-if="phase==='playing' && !hud.awaitUpgrade" class="camp-touch"><div ref="joystick" class="camp-stick" role="group" aria-label="拖动摇杆移动" @pointerdown.stop.prevent="stickStart" @pointermove.stop.prevent="stickMove" @pointerup.stop="stickStop" @pointercancel.stop="stickStop" @lostpointercapture="stickStop"><span :style="{transform:`translate(${stick.x*22}px,${stick.z*22}px)`}">✥</span></div><div><button type="button" @pointerdown.stop.prevent="fire=true" @pointerup.stop="fire=false" @pointercancel.stop="fire=false" @pointerleave="fire=false">防卫</button><button type="button" @click.stop="dash=true;stage.focus({preventScroll:true})">冲刺</button><button type="button" @click.stop="interact">采集 / 维修</button></div></div>
      <div v-if="phase!=='playing'||hud.awaitUpgrade||error" class="camp-overlay"><div><p class="section-kicker">{{hud.awaitUpgrade?'A NEW DAWN':'EMBER CAMP / 01'}}</p><h2>{{error?'换个模式继续。':hud.awaitUpgrade?'黎明补给，三选一。':phase==='won'?'你的营地，等到了救援。':phase==='lost'?'灯灭了。再建一座营地。':phase==='paused'?'营地时间已暂停。':'第一夜，先做好准备。'}}</h2><p>{{error|| (hud.awaitUpgrade?'建设、袭击与计时全部暂停，选择后进入下一天。':phase==='ready'?'先采集，建菜地与净水站；守住三夜。初始资源能建基础设施，也能选择先扩充火力。':phase==='paused'?'返回后手动继续。离开页面或切换标签页也会暂停。':hud.notes.at(-1))}}</p>
        <div v-if="hud.awaitUpgrade" class="camp-upgrades"><button v-for="item in hud.upgrades" :key="item.id" type="button" @click.stop="upgrade(item.id)"><strong>{{item.name}}</strong><span>{{item.note}}</span></button></div><template v-else-if="!error"><label v-if="phase!=='paused'">难度<select v-model="difficulty"><option value="normal">标准生存</option><option value="relaxed">轻松建设 · 夜晚更晚、敌人更慢</option></select></label><button type="button" class="button button-primary" @click.stop="phase==='paused'?resume():start()">{{phase==='paused'?'继续营地':phase==='ready'?'开始建设':'重新建营'}}</button><p v-if="['won','lost'].includes(phase)" class="camp-run-summary">采集 {{hud.harvests}} 次 · 建造 {{hud.buildCount}} 座 · 击退 {{hud.kills}} 个敌人</p></template><RouterLink v-else class="button button-primary" to="/wasteland?mode=story">打开剧情模式</RouterLink>
      </div></div></div>
      <div class="construction-bar"><header><h2>建造菜单</h2><button v-if="selected" type="button" class="text-button" @click="selected='';cursor=null;draw()">取消建造 ×</button></header><div class="building-cards"><button v-for="item in BUILDINGS" :key="item.id" :data-building="item.id" type="button" :disabled="phase!=='playing'||hud.awaitUpgrade" :aria-pressed="selected===item.id" @click="selectBuilding(item.id)"><span class="building-glyph" aria-hidden="true">{{glyphs[item.id]}}</span><strong>{{item.name}}</strong><small>{{item.wood}} 木材 · {{item.scrap}} 零件{{item.food?' · 1 食物':''}}</small><span>{{item.note}}</span></button></div><div v-if="selected" class="blueprint-controls"><p :class="{'invalid-placement':!target?.ok}">{{target?.reason}} · 格位 {{target?.x}}, {{target?.z}}</p><div><button v-for="(offset,label) in offsets" :key="label" type="button" :aria-label="`格位${label}`" @click="adjust(...offset)">{{label}}</button><button class="button button-primary" type="button" :disabled="!target?.ok" @click="place">确认建造</button></div></div><p class="camp-note">建筑需在角色 7 米内；绿格可以放置，红格说明占用或资源不足。点击场景或使用格位按钮放置。移动与建造不扣除食物，黎明统一消耗。</p></div>
    </section><aside class="camp-sidebar"><section class="camp-checklist"><p class="section-kicker">YOUR CAMP / THREE NIGHTS</p><h2>让生活继续。</h2><ul><li :class="{done:hud.buildings.some(b=>b.kind==='garden')}">建设菜地，持续供给食物</li><li :class="{done:hud.buildings.some(b=>b.kind==='water')}">建设净水站，持续供水</li><li :class="{done:hud.power.demand<=hud.power.capacity}">保证炮塔有电</li><li :class="{done:hud.day>3}">守住三个夜晚</li></ul><button type="button" class="button button-secondary" :disabled="phase!=='playing'||hud.night||hud.awaitUpgrade" @click="night">准备好了，迎接夜晚</button></section>
      <section class="camp-map"><h3>营地地图 <small>北 ↑</small></h3><svg viewBox="-16 -16 32 32" role="img" aria-label="固定北向营地地图"><rect x="-15" y="-15" width="30" height="30" rx="1" fill="#edf1e8" /><path d="M-15 0h30M0-15v30" stroke="#d4decc" stroke-width="2" /><rect v-for="r in CAMP_ROCKS" :key="`${r.x},${r.z}`" :x="r.x-1" :y="r.z-1" width="2" height="2" fill="#b4bbae" /><circle v-for="node in hud.nodes.filter(n=>n.remaining)" :key="node.id" :cx="node.x" :cy="node.z" r=".55" :fill="nodeColors[node.kind]" /><rect v-for="building in hud.buildings" :key="building.id" :x="building.x-.6" :y="building.z-.6" width="1.2" height="1.2" :fill="building.kind==='turret'&&!building.powered?'#bd7a65':'#609b8a'" /><circle v-for="enemy in hud.enemies" :key="enemy.id" :cx="enemy.x" :cy="enemy.z" r=".6" fill="#c87367" /><path d="M-1-1h2v2h-2Z" fill="#419ca2" /><circle :cx="hud.player.x" :cy="hud.player.z" r=".65" fill="#0071e3" stroke="#fff" stroke-width=".25" /></svg><p>蓝点＝你 · 青方格＝设施 · 红点＝敌人<br>绿/灰/橙/蓝点＝木材/零件/食物/水</p></section>
      <section class="camp-log"><h3>营地记录</h3><ol aria-live="polite"><li v-for="(entry,i) in hud.notes" :key="i">{{entry}}</li></ol></section><p class="camp-note">原创建模与游戏规则，默认静音。所有玩法在本机运行，不调用 API，不自动保存进度。音效为程序生成，可随时关闭。</p>
    </aside></div>
  </main>
</template>
<script setup>
import { computed,onMounted,onUnmounted,ref,shallowRef,watch } from 'vue'
import { RouterLink } from 'vue-router'
import { BUILDINGS,CAMP_ROCKS,createSettlement,placement,buildCamp,campInteract,stepSettlement,upgradeCamp,startNight } from '../features/wasteland/settlement'
import { createSettlementScene } from '../features/wasteland/settlementScene'
import { screenDirection } from '../features/wasteland/expedition'
import { useExpandedScene } from '../utils/useExpandedScene'
const stage=ref(null),mount=ref(null),joystick=ref(null),phase=ref('ready'),error=ref(''),selected=ref(''),cursor=ref(null),difficulty=ref('normal'),help=ref(false),sound=ref(false),fire=ref(false),dash=ref(false),stick=ref({x:0,z:0})
const resourceNames={wood:'木材',scrap:'零件',food:'食物',water:'饮水'},nodeColors={wood:'#79a471',scrap:'#98a9b2',food:'#d8a268',water:'#6caed5'},glyphs={wall:'▥',turret:'⌖',generator:'ϟ',garden:'♧',water:'≈'},offsets={'向左':[-2,0],'向北':[0,-2],'向南':[0,2],'向右':[2,0]}
let state=createSettlement(),scene,frame,last=0,painted=0,published=0,motion,audio,lastBeep=0,pointerId=null;const keys=new Set()
const hud=shallowRef(structuredClone(state));const {expanded,toggle:toggleScene}=useExpandedScene(()=>pause())
const target=computed(()=>cursor.value&&selected.value?placement(hud.value,selected.value,cursor.value.x,cursor.value.z):null)
function beep(pitch=500){if(!sound.value||!audio||audio.state!=='running'||performance.now()-lastBeep<80)return;lastBeep=performance.now();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(pitch,audio.currentTime);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.09);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.1);osc.onended=()=>{osc.disconnect();gain.disconnect()}}
watch(sound,async enabled=>{try{if(!enabled){await audio?.suspend();return}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){sound.value=false;return}audio||=new Audio();await audio.resume();beep()}catch{sound.value=false}})
function draw(){scene?.render(state,target.value,motion?.matches)}
function sync(){hud.value=structuredClone(state);draw()}
function clearInput(){keys.clear();fire.value=false;dash.value=false;stick.value={x:0,z:0};pointerId=null}
function pause(){if(phase.value!=='playing')return;phase.value='paused';cancelAnimationFrame(frame);clearInput();sync()}
function resume(){if(!scene||error.value)return;clearInput();phase.value='playing';last=0;stage.value?.focus({preventScroll:true});cancelAnimationFrame(frame);frame=requestAnimationFrame(tick)}
function start(){state=createSettlement('余烬营地',difficulty.value);selected.value='';cursor.value=null;sync();resume();beep(620)}
function tick(now){if(phase.value!=='playing'||state.awaitUpgrade)return;const dt=last?Math.min((now-last)/1000,.05):0;last=now;const x=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'))+stick.value.x,z=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'))+stick.value.z,move=screenDirection(x,z,Math.PI/4),kills=state.kills
  stepSettlement(state,{...move,fire:fire.value||keys.has(' '),dash:dash.value||keys.has('shift')},dt);dash.value=false;if(state.kills>kills)beep(700)
  if(now-published>100||state.status!=='playing'||state.awaitUpgrade){hud.value=structuredClone(state);published=now}if(now-painted>1000/30||state.status!=='playing'||state.awaitUpgrade){draw();painted=now}
  if(state.status!=='playing'){phase.value=state.status;clearInput();return}if(state.awaitUpgrade){clearInput();return}frame=requestAnimationFrame(tick)
}
function focus(event){if(!event.target.closest('button,a,select'))stage.value?.focus({preventScroll:true})}
function point(event){if(!selected.value||phase.value!=='playing'||event.target.closest('button,.camp-stick'))return;const at=scene?.world(event.clientX,event.clientY);if(at)cursor.value=at;draw()}
function selectBuilding(id){selected.value=id;const p=state.player;const candidates=[[2,0],[0,2],[-2,0],[0,-2],[4,0],[0,4]];cursor.value=candidates.map(([dx,dz])=>({x:p.x+dx,z:p.z+dz})).find(at=>placement(state,id,at.x,at.z).ok)||{x:p.x+2,z:p.z};draw()}
function adjust(dx,dz){if(!cursor.value)return;cursor.value={x:Math.round(cursor.value.x/2)*2+dx,z:Math.round(cursor.value.z/2)*2+dz};draw()}
function place(){if(phase.value!=='playing'||!target.value)return;if(buildCamp(state,selected.value,target.value.x,target.value.z))beep(450);sync();stage.value?.focus({preventScroll:true})}
function placeScene(event){if(event.target.closest('button,a,select,.camp-overlay,.camp-touch')||!selected.value)return;point(event);place()}
function interact(){if(phase.value!=='playing')return;if(campInteract(state))beep(360);sync();stage.value?.focus({preventScroll:true})}
function night(){if(phase.value==='playing'){startNight(state);sync();stage.value?.focus({preventScroll:true})}}
function upgrade(id){if(upgradeCamp(state,id)){sync();resume();beep(820)}}
function keydown(event){if(event.ctrlKey||event.metaKey||event.altKey||document.activeElement!==stage.value)return;const key=event.key.toLowerCase();if(!['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','shift',' ','e','escape'].includes(key))return;event.preventDefault();if(key==='escape'&&!event.repeat){phase.value==='paused'?resume():pause();return}if(phase.value!=='playing'||state.awaitUpgrade)return;if(key==='e'){if(!event.repeat)interact()}else keys.add(key)}
function keyup(event){keys.delete(event.key.toLowerCase())}
function stickStart(event){if(phase.value!=='playing')return;pointerId=event.pointerId;event.currentTarget.setPointerCapture(event.pointerId);stickMove(event)}
function stickMove(event){if(pointerId!==event.pointerId)return;const r=joystick.value.getBoundingClientRect(),x=(event.clientX-r.left-r.width/2)/26,z=(event.clientY-r.top-r.height/2)/26,len=Math.max(1,Math.hypot(x,z));stick.value={x:x/len,z:z/len}}
function stickStop(){pointerId=null;stick.value={x:0,z:0}}
function visibility(){if(document.hidden)pause()}
onMounted(()=>{motion=matchMedia('(prefers-reduced-motion: reduce)');try{scene=createSettlementScene(mount.value,state);draw()}catch(ex){error.value=ex.message}window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',pause);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{cancelAnimationFrame(frame);clearInput();scene?.dispose();audio?.close();window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',pause);document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>
